<?php require __DIR__.'/includes/auth.php';require_admin();require __DIR__.'/config/database.php';$is_admin=true;if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['delete_id'])){$pdo->prepare('DELETE FROM items WHERE id=?')->execute([(int)$_POST['delete_id']]);header('Location: inventory.php?deleted=1');exit;}$items=$pdo->query('SELECT items.*,categories.name category_name FROM items LEFT JOIN categories ON items.category_id=categories.id ORDER BY items.id DESC')->fetchAll();?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SIMS | Inventory</title><link rel="stylesheet" href="assets/css/style.css"><style>.action{border:0;background:#f2f1ff;color:#4f46e5;border-radius:5px;padding:7px;cursor:pointer;text-decoration:none;font-size:12px}.delete{background:#fff0f2;color:#d23550}.toolbar{margin-bottom:17px;display:flex;justify-content:space-between;gap:10px}.toolbar input{border:1px solid #e8e8f0;border-radius:7px;padding:10px;width:260px}.success{background:#dcfce7;color:#15803d;padding:10px;border-radius:7px;font-size:13px}</style></head><body class="dashboard-page"><aside class="sidebar"><div class="logo"><span>✎</span><div><strong>SIMS</strong><small>Stationery Inventory</small></div></div><nav><a href="dashboard.php">▦ Dashboard</a><a class="active" href="inventory.php">▤ Inventory</a><a href="stock_movement.php">↕ Stock movement</a><?php if($is_admin):?><a href="admin_requests.php">✉ Staff requests</a><a href="manage_users.php">♙ Users</a><?php else:?><a href="request_stationery.php">✉ Request stationery</a><?php endif;?></nav><a class="logout" href="logout.php">⇥ Sign out</a></aside><main class="dashboard"><header><div><p class="eyebrow">INVENTORY</p><h1>Inventory List</h1></div><?php if($is_admin):?><a class="primary-btn" style="width:auto" href="item_form.php">+ Add New Item</a><?php endif;?></header><?php if(isset($_GET['deleted'])):?><p class="success">Item deleted successfully.</p><?php endif;?><section class="content-card"><div class="toolbar"><input id="search" placeholder="Search items..."><span class="muted"><?=count($items)?> items</span></div><table><thead><tr><th>Item</th><th>Category</th><th>Current stock</th><th>Status</th><?php if($is_admin):?><th>Action</th><?php endif;?></tr></thead><tbody id="items"><?php if(!$items):?><tr><td colspan="5">No inventory items yet.</td></tr><?php endif;?><?php foreach($items as $item):$out=(int)$item['quantity']<=0;?><tr><td><strong><?=htmlspecialchars($item['name'])?></strong></td><td><?=htmlspecialchars($item['category_name']??'Uncategorised')?></td><td><?= (int)$item['quantity']?></td><td><span class="badge <?=$out?'low':'good'?>"><?=$out?'Out of Stock':'In Stock'?></span></td><?php if($is_admin):?><td><a class="action" href="item_form.php?id=<?=(int)$item['id']?>">Edit</a> <form style="display:inline" method="post" onsubmit="return confirm('Delete this item?')"><input type="hidden" name="delete_id" value="<?=(int)$item['id']?>"><button class="action delete">Delete</button></form></td><?php endif;?></tr><?php endforeach;?></tbody></table></section></main><script src="assets/js/app.js"></script></body></html>
